from itertools import product


def marginal(probs, holds, evidence=None):
    names = sorted(probs)
    total = 0.0
    hit = 0.0
    for bits in product((False, True), repeat=len(names)):
        world = dict(zip(names, bits))
        weight = 1.0
        for name, value in world.items():
            weight *= probs[name] if value else 1.0 - probs[name]
        if evidence is not None and not evidence(world):
            continue
        total += weight
        if holds(world):
            hit += weight
    if total == 0.0:
        raise ValueError("the observation has probability zero")
    return hit / total
